class RecursionTest {
	private int $recursions = 0;
	private int $maxRecursions = 2;
	private array $testLabels = [ 'foo', 'bar', 'baz', 'ignore_me' ];

	public function incrementRecursions(): void {
		if ($this->recursions < $this->maxRecursions) {
			$this->recursions++;
		}
	}

	public function isMaxRecursionsReached(): bool {
		return $this->recursions >= $this->maxRecursions;
	}

	public function getRemainingRecursions(): int {
		return $this->maxRecursions - $this->recursions;
	}

	public function resetRecursions(): void {
		$this->recursions = 0;
	}

	public function getTestLabels(): array {
		return $this->testLabels;
	}

	public function filterTestLabels(array $labels): array {
		return array_filter($labels, function($label) {
			return !in_array($label, $this->testLabels);
		});
	}
}
