const executeLintRequest = async (doc) => {
    const rest = new mw.Rest();
    let controller = new AbortController();

    try {
        const response = await rest.post('/v1/transform/wikitext/to/lint', {
            wikitext: doc.toString(),
            signal: controller.signal
        }, { timeout: 30000 });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        return await response.json();
    } catch (error) {
        mw.log.warn('[CodeMirror] Lint request failed:', error);
        // Optionally, handle specific errors like timeout separately
        if (error.name === 'AbortError') {
            mw.log.warn('[CodeMirror] Lint request aborted.');
        }
    } finally {
        // Clean up the controller to allow garbage collection
        controller = null;
    }
};

// Usage example
const doc = new DOMParser().parseFromString(wikitext, 'text/html');
executeLintRequest(doc);
```

