const colorCache = new Map();

function getColorForImage(imageFile) {
    const cachedColor = colorCache.get(imageFile);
    if (cachedColor) {
        return cachedColor;
    }

    // Calculate the color using FastAverageColor
    const fastAverageColor = new FastAverageColor();
    const colorResult = fastAverageColor.getColorSync(imageFile);

    // Store the result in the cache
    colorCache.set(imageFile, colorResult);

    return colorResult;
}
